function frameLooksMutationRequest(text=''){const norm=aiNorm(text);return /(?:создай|создать|создавай|заведи|завести|добавь|добавить|запиши|записать|внеси|внести|сохрани|сохранить|измени|изменить|поменяй|поменять|обнови|обновить|удали|удалить|отметь|отметить|поставь|поставить|закрой|закрыть)/.test(norm)||/(?:сделай|сформируй|сформировать|подготовь|подготовить|оформи|оформить|составь|составить|сгенерируй|сгенерировать|выкати|выкатить|давай)[^.!?]{0,120}(?:карточк|объект|заказ|документ|акт|договор|сч[её]т|кп|предложени|переч)/.test(norm)||/(?:документ|акт|кп|коммерческ[^.!?]{0,30}предложени|переч)[^.!?]{0,100}(?:сделай|сформируй|подготовь|оформи|составь|сгенерируй|выкати)/.test(norm)}
function frameAffirmsClarification(text=''){return /^(?:да|ага|угу|верно|точно|давай|создавай|делай|оформляй|записывай|сохраняй)(?:[\s,.!].*)?$/.test(aiNorm(text))}
