function frameChatHtml(){const items=frameChatMessages(),latestUndo=frameLatestUndoLogId();const body=!items.length?`<div class="frameChatWelcome"><span class="frameChatOrb">✦</span><div><strong>Здорово! Я Мира, помощница в FRAME.</strong><p>Могу вести объекты и расчёты, находить карточки и фотографии, готовить документы, искать свежую информацию и просто нормально поговорить. Скажи как есть — разберёмся.</p></div></div>`:items.map(m=>{const p=m.role==='assistant'&&m.status==='pending'&&m.draft,s=m.status==='applied'?'✓ Записано':m.status==='cancelled'?'Отменено':m.status==='error'?'Не выполнено':'',logId=String(m.receipt?.logId||''),undo=m.status==='applied'&&logId&&logId===latestUndo;return `<article class="frameChatMessage ${m.role==='user'?'fromUser':'fromFrame'} ${p?'hasPlan':''}"><div class="frameChatBubble"><small class="frameChatTime">${esc(frameChatTime(m.at))}</small><div class="frameChatText">${esc(m.text||'')}</div>${frameChatSourcesHtml(m)}${p?framePlanHtml(m.draft):''}${p?framePendingControls(m):''}${frameChatLinksHtml(m)}${s?`<div class="frameChatStatus ${m.status}">${s}${undo?` <button type="button" data-chat-undo="${esc(logId)}" data-chat-message="${esc(m.id)}">Отменить</button>`:''}</div>`:''}</div></article>`}).join('');return body+frameThinkingHtml()}
