checkAiBrain=async function({toastResult=true}={}){const base=aiServerUrl(),token=aiServerToken(),credential=frameOwnerCredentialKey(base,token),current=()=>base===aiServerUrl()&&token===aiServerToken();frameOwnerVerifiedCredential='';if(!base){aiRecordAuthenticatedHealth('',{url:base,authenticated:false});aiBrainStatus={ok:false,ownerTestObservability:false,ownerDestination:'',message:'Адрес не задан'};return aiBrainStatus}try{const d=await aiBrainFetch('/health',{method:'GET'},{base,token});if(!current())return aiBrainStatus||{ok:false,message:'Настройки AI Brain изменились'};const healthMode=String(d.mode||d.detail?.mode||''),fieldVerified=aiRecordAuthenticatedHealth(healthMode,{url:base,authenticated:!!token&&!!d.ok}),ok=!!d.ok&&(!aiConfiguredFieldSafe(base)||fieldVerified),ownerTestObservability=ok&&d.owner_test_observability===true,ownerDestination=ownerTestObservability?await frameOwnerCurrentDestination(base,token):'';if(!current())return aiBrainStatus||{ok:false,message:'Настройки AI Brain изменились'};frameOwnerVerifiedCredential=ownerTestObservability?credential:'';aiBrainStatus={ok,provider:d.provider||'',model:d.model||'',mode:healthMode,detail:d.detail||{},ownerTestObservability,ownerDestination,message:ok?'Готов к работе':aiConfiguredFieldSafe(base)?'Безопасный режим сервера не подтверждён':'AI Brain пока не готов'};if(ownerTestObservability)frameOwnerScheduleFlush(0,{reset:true});if(toastResult)toast(ok?'FRAME на связи':aiBrainStatus.message);return aiBrainStatus}catch(e){if(!current())return aiBrainStatus||{ok:false,message:'Настройки AI Brain изменились'};frameOwnerVerifiedCredential='';aiRecordAuthenticatedHealth('',{url:base,authenticated:false});aiBrainStatus={ok:false,ownerTestObservability:false,ownerDestination:'',message:String(e?.message||e)};if(toastResult)toast('FRAME не может связаться с AI Brain');return aiBrainStatus}finally{if(route==='ai')requestAnimationFrame(frameRenderConnectionDot)}};
