renderAiView=function(){frameRestorePending();if(!frameTopic()){const preferred=routeState.aiTarget||aiDefaultTargetKey();if(preferred&&aiTargetByKey(preferred))frameSetTopic(preferred)}const mic=!!(window.SpeechRecognition||window.webkitSpeechRecognition),recording=frameTestTranscriptActive();return `<section class="frameChatView"><header class="frameChatTop"><div class="frameChatTitle">FRAME <i id="frameConnectionDot" class="frameConnectionDot ${aiBrainStatus?.ok?'ok':aiBrainStatus?'bad':'wait'}"></i><small>${esc(frameTopicLabel()||'готова помочь')}</small></div><button id="frameTestBtn" class="frameTestButton ${recording?'active':''}" type="button" aria-label="${recording?'Личная тестовая запись включена':'Открыть личный тест'}"><i></i>${recording?'ЗАПИСЬ':'ЛИЧНЫЙ ТЕСТ'}</button></header><main id="frameChatFeed" class="frameChatFeed">${frameChatHtml()}</main><footer class="frameChatComposer"><button id="frameAttachBtn" class="frameComposerIcon" type="button" aria-label="Добавить">＋</button><div class="frameComposerField"><textarea id="aiCommandInput" rows="1" placeholder="Сообщение FRAME"></textarea><div id="frameVoicePanel" class="frameVoicePanel" hidden><span class="frameVoiceBars" aria-hidden="true">${Array.from({length:13},(_,i)=>`<i style="--bar:${i}"></i>`).join('')}</span><strong>Слушаю…</strong><small id="frameVoiceTimer">00:00</small></div></div><button id="aiMicBtn" class="frameComposerIcon mic" type="button" ${mic?'':'disabled'} aria-label="${mic?'Начать диктовку':'Диктовка недоступна'}">🎙️</button><button id="aiAnalyzeBtn" class="frameSendBtn" type="button" aria-label="Отправить">↑</button></footer></section>`}
