function frameHardClearComposer(){frameVoiceBase='';frameVoiceFinal='';frameVoiceInterim='';frameComposerDraftSession='';const i=$('aiCommandInput');if(i){i.value='';i.style.height='auto';i.style.overflowY='hidden'}}
analyzeAiInput=async function(){
  if(aiAnalyzing||frameThinking)return toast('FRAME уже отвечает — секунду');
  if(frameApplyingDraftId)return toast('FRAME записывает изменение — секунду');
  aiAnalyzing=true;const btn=$('aiAnalyzeBtn');if(btn){btn.disabled=true;btn.textContent='…'}let turnId='',started=performance.now();
  try{
    if(frameVoiceWanted||aiRecognition||frameVoiceStopping)await frameStopVoice(true,true);
    const input=$('aiCommandInput'),text=String(input?.value||frameComposerDraftSession||'').trim();if(!text){toast('Сначала скажите или напишите сообщение');return}
    frameVoiceSession++;frameHardClearComposer();
    const detected=frameDetectTarget(text);if(detected)frameSetTopic(detected);else if(frameTopic())routeState.aiTarget=frameTopic();
    const old=frameRestorePending();if(old?.chatId){aiRevokeDraftAuthorization(old);frameUpdateChat(old.chatId,{status:'cancelled',draft:null})}aiDraft=null;frameClearPending();
    const previousMutation=frameMutationClarificationSession,directMutation=frameLooksMutationRequest(text),mutationIntent=directMutation||(!!previousMutation&&frameAffirmsClarification(text));frameMutationClarificationSession='';
    turnId=uid();started=performance.now();frameAddChat({role:'user',text,status:'done',turnId});frameThinking=true;frameRefreshChat();
    const localOpen=mutationIntent?null:frameLocalOpenIntent(text);
    if(localOpen){frameAddChat({role:'assistant',text:localOpen.text,status:'done',turnId,links:localOpen.links,trace:{provider:'FRAME local navigation',model:VERSION,mode:'local',outcome:'answer',round_trip_ms:Math.round(performance.now()-started),proposed_actions:[],policy_blocked_actions:[]}});return}
    let draft,response=null;if(aiServerUrl()){response=await requestAiBrain(text);if(mutationIntent)response={...response,meta:{...(response?.meta||{}),mutation_intent:true}};draft=brainDraftFromResponse(text,response)}else draft=parseAiCommand(text,frameTopic()||routeState.aiTarget);
    if(draft?.targetKey&&aiTargetByKey(draft.targetKey)){const explicit=frameDetectTarget(text);if(explicit)frameSetTopic(explicit);else if(frameTopic())draft.targetKey=frameTopic()}
    frameAttachTargetSnapshot(draft);const policyError=frameDraftPolicyError(draft);if(policyError)draft={...draft,ok:false,source:'brain',blocked:true,error:policyError,text};
    if(draft?.clarification&&mutationIntent)frameMutationClarificationSession=directMutation?text:previousMutation;const trace=frameBuildTestTrace(draft,response,Math.round(performance.now()-started));
    if(draft?.ok&&draft.type==='read_answer')frameAddChat({role:'assistant',text:draft.summary,status:'done',turnId,trace,sources:draft.sources||[]});
    else if(draft?.ok){const m=frameAddChat({role:'assistant',text:'Я поняла. Проверь, что именно записать:',status:'pending',draft,turnId,trace});draft.chatId=m.id;m.draft.chatId=m.id;frameUpdateChat(m.id,{draft:m.draft});aiDraft=draft;frameSavePending(draft)}
    else frameAddChat({role:'assistant',text:draft?.error||'Не разобрала конкретный фрагмент. Скажите его чуть иначе?',status:draft?.blocked?'error':'done',turnId,trace,sources:draft?.sources||[]});
  }catch(e){console.error(e);if(turnId)frameAddChat({role:'assistant',text:'Не смогла связаться с FRAME. Я ничего не изменила — проверьте домашний компьютер и подключение.',status:'error',turnId,trace:frameBuildTestTrace(null,null,Math.round(performance.now()-started),'request_failed')});else toast('Не получилось отправить сообщение — попробуйте ещё раз')}
  finally{frameThinking=false;aiAnalyzing=false;if(btn){btn.disabled=false;btn.textContent='↑'}frameRefreshChat()}
}

async function frameAcquireWakeLock(){if(!('wakeLock' in navigator)||document.visibilityState!=='visible'||frameVoiceWakeLock)return frameVoiceWakeLock;if(frameWakeAcquirePromise)return frameWakeAcquirePromise;frameWakeAcquirePromise=(async()=>{try{const lock=await navigator.wakeLock.request('screen');if(document.visibilityState!=='visible'||(!frameVoiceWanted&&!frameComposerWakeWanted)){try{await lock.release()}catch(e){}return null}frameVoiceWakeLock=lock;lock.addEventListener('release',()=>{if(frameVoiceWakeLock===lock)frameVoiceWakeLock=null});return lock}catch(e){return null}finally{frameWakeAcquirePromise=null}})();return frameWakeAcquirePromise}
async function frameReleaseWakeLock(){try{if(frameWakeAcquirePromise)await frameWakeAcquirePromise;if(document.visibilityState==='visible'&&(frameVoiceWanted||frameComposerWakeWanted))return frameVoiceWakeLock;const lock=frameVoiceWakeLock;frameVoiceWakeLock=null;await lock?.release()}catch(e){}finally{if(document.visibilityState!=='visible'||(!frameVoiceWanted&&!frameComposerWakeWanted))frameVoiceWakeLock=null}}
