    if(aiRecognition===old){try{old?.abort?.()}catch(e){}aiRecognition=null}const text=frameVoiceText();if(keepText&&text){frameComposerDraftSession=text;frameSetComposerText(text)}else if(!keepText){frameComposerDraftSession='';const input=$('aiCommandInput');if(input)input.value=''}frameVoiceBase='';frameVoiceFinal='';frameVoiceInterim='';if(session===frameVoiceSession)frameVoiceSession++;frameVoiceStopping=false;frameVoiceButton(false);frameRefreshWakeLock();if(!silent&&keepText&&text)toast('Готово — проверьте текст и отправляйте');return text
